import sqlite3
from typing import List, Dict, Any, Tuple, Optional, Set

# ---------- Required fixed configuration ----------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}

# ---------- Helpers ----------

def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def chunk_list(xs: List[Any], n: int) -> List[List[Any]]:
    return [xs[i:i+n] for i in range(0, len(xs), n)]


def get_single_user_id_by_name(user_conn: sqlite3.Connection, name: str) -> str:
    rows = user_conn.execute(
        "SELECT user_id, name FROM user WHERE name = ? LIMIT 5", (name,)
    ).fetchall()
    if not rows:
        raise ValueError(f"No user found with name={name}")
    # If multiple, take first; in real usage you may disambiguate by review_count, yelping_since, etc.
    return rows[0]["user_id"]


def get_friend_ids_from_neo4j(carl_user_id: str) -> Optional[List[str]]:
    try:
        from neo4j import GraphDatabase
    except Exception:
        return None

    try:
        driver = GraphDatabase.driver(neo4j_config['neo4j_uri'], auth=neo4j_config['neo4j_auth'])
        cypher = (
            "MATCH (u:User {user_id:$uid})-[:FRIENDS_WITH]-(f:User) "
            "RETURN DISTINCT f.user_id AS friend_id"
        )
        with driver.session() as session:
            recs = session.run(cypher, uid=carl_user_id).data()
        driver.close()
        friend_ids = [r["friend_id"] for r in recs if r.get("friend_id")]
        return friend_ids
    except Exception:
        return None


def get_friend_ids_from_sqlite_user_table(user_conn: sqlite3.Connection, carl_user_id: str) -> List[str]:
    # Yelp JSON user has 'friends' as comma-separated string in many derived SQLite schemas.
    row = user_conn.execute(
        "SELECT friends FROM user WHERE user_id = ?", (carl_user_id,)
    ).fetchone()
    if not row:
        return []
    friends_val = row["friends"]
    if friends_val is None:
        return []
    friends_val = friends_val.strip()
    if friends_val == "" or friends_val.lower() == "none":
        return []
    # Common formats: "id1, id2, id3" or already list-like
    return [x.strip() for x in friends_val.split(",") if x.strip()]


def get_edmonton_chinese_businesses(biz_conn: sqlite3.Connection) -> List[sqlite3.Row]:
    # Adjust city casing if needed.
    q = (
        "SELECT business_id, name, address, city, state, postal_code, stars, categories "
        "FROM business "
        "WHERE city = ? AND categories LIKE ?"
    )
    return biz_conn.execute(q, ("Edmonton", "%Chinese%",)).fetchall()


def get_business_ids_with_keyword_photos(photo_conn: sqlite3.Connection) -> Set[str]:
    # caption may be NULL; we use lower(caption) LIKE.
    q = (
        "SELECT DISTINCT business_id "
        "FROM photo "
        "WHERE caption IS NOT NULL AND (lower(caption) LIKE ? OR lower(caption) LIKE ?)"
    )
    rows = photo_conn.execute(q, ("%dim sum%", "%fried rice%",)).fetchall()
    return {r["business_id"] for r in rows if r["business_id"]}


def try_milvus_business_ids_by_text_queries(text_queries: List[str], topk: int = 200) -> Set[str]:
    """Optional: Use Milvus photo_vector to retrieve similar photos for 'dim sum'/'fried rice'.
    Requires a CLIP-like text encoder compatible with stored photo embeddings.
    If dependencies or Milvus not available, returns empty set.
    """
    try:
        from pymilvus import connections, Collection
    except Exception:
        return set()

    # Text encoder (CLIP). If not available, skip.
    try:
        import torch
        from transformers import CLIPTokenizer, CLIPTextModel
    except Exception:
        return set()

    try:
        connections.connect(
            alias="default",
            host=milvus_config['milvus_host'],
            port=milvus_config['milvus_port']
        )
        col = Collection(milvus_config['milvus_collections']['photos'])

        # NOTE: This assumes photo vectors were built with CLIP-ViT-B/32 text/image joint space.
        tokenizer = CLIPTokenizer.from_pretrained("openai/clip-vit-base-patch32")
        text_model = CLIPTextModel.from_pretrained("openai/clip-vit-base-patch32")
        text_model.eval()

        def embed_text(t: str) -> List[float]:
            inputs = tokenizer([t], padding=True, return_tensors="pt")
            with torch.no_grad():
                out = text_model(**inputs)
                # pooled_output shape [1, hidden]
                vec = out.pooler_output[0].cpu().numpy().astype("float32")
            # L2 normalize
            import numpy as np
            vec = vec / (np.linalg.norm(vec) + 1e-12)
            return vec.tolist()

        business_ids: Set[str] = set()

        # You may need to adjust field names to your Milvus schema.
        # Common pattern: primary key 'photo_id', vector field 'embedding', and a scalar 'business_id'.
        vector_field = "embedding"  # change if your schema uses different name
        output_fields = ["photo_id", "business_id"]

        for tq in text_queries:
            vec = embed_text(tq)
            res = col.search(
                data=[vec],
                anns_field=vector_field,
                param={"metric_type": "IP", "params": {"nprobe": 16}},
                limit=topk,
                output_fields=output_fields
            )
            for hits in res:
                for h in hits:
                    ent = getattr(h, "entity", None)
                    if ent is None:
                        continue
                    bid = None
                    try:
                        bid = ent.get("business_id")
                    except Exception:
                        bid = None
                    if bid:
                        business_ids.add(bid)

        return business_ids

    except Exception:
        return set()


def get_friend_reviews_for_businesses(
    review_conn: sqlite3.Connection,
    friend_ids: List[str],
    business_ids: List[str]
) -> List[sqlite3.Row]:
    if not friend_ids or not business_ids:
        return []

    # SQLite has a parameter limit; chunk.
    out: List[sqlite3.Row] = []
    biz_chunks = chunk_list(business_ids, 900)
    friend_chunks = chunk_list(friend_ids, 900)

    for fc in friend_chunks:
        for bc in biz_chunks:
            q = (
                f"SELECT user_id, business_id, stars "
                f"FROM review "
                f"WHERE user_id IN ({','.join(['?']*len(fc))}) "
                f"AND business_id IN ({','.join(['?']*len(bc))})"
            )
            out.extend(review_conn.execute(q, tuple(fc + bc)).fetchall())
    return out


def get_user_names(user_conn: sqlite3.Connection, user_ids: List[str]) -> Dict[str, str]:
    if not user_ids:
        return {}
    mp: Dict[str, str] = {}
    for chunk in chunk_list(user_ids, 900):
        q = f"SELECT user_id, name FROM user WHERE user_id IN ({','.join(['?']*len(chunk))})"
        rows = user_conn.execute(q, tuple(chunk)).fetchall()
        for r in rows:
            mp[r["user_id"]] = r["name"]
    return mp


def main():
    # Connect SQLite DBs
    user_conn = connect_sqlite(sqlite_paths["user"])
    biz_conn = connect_sqlite(sqlite_paths["business"])
    photo_conn = connect_sqlite(sqlite_paths["photo"])
    review_conn = connect_sqlite(sqlite_paths["review"])

    try:
        # 1) Carl user_id
        carl_user_id = get_single_user_id_by_name(user_conn, "Carl")

        # 2) Friends
        friend_ids = get_friend_ids_from_neo4j(carl_user_id)
        if friend_ids is None or len(friend_ids) == 0:
            friend_ids = get_friend_ids_from_sqlite_user_table(user_conn, carl_user_id)

        if not friend_ids:
            raise ValueError("Carl has no friends found from Neo4j or SQLite fallback.")

        # 3) Edmonton Chinese businesses
        edm_chinese = get_edmonton_chinese_businesses(biz_conn)
        edm_biz_by_id = {r["business_id"]: r for r in edm_chinese}
        edm_biz_ids = list(edm_biz_by_id.keys())

        if not edm_biz_ids:
            raise ValueError("No Edmonton Chinese businesses found.")

        # 4) Businesses with dim sum / fried rice photos
        keyword_biz_ids = get_business_ids_with_keyword_photos(photo_conn)

        # Optional Milvus vector recall
        milvus_biz_ids = try_milvus_business_ids_by_text_queries(["dim sum", "fried rice"], topk=200)

        # Combine, then restrict to Edmonton+Chinese
        target_biz_ids = (keyword_biz_ids | milvus_biz_ids) & set(edm_biz_ids)
        target_biz_ids = list(target_biz_ids)

        if not target_biz_ids:
            raise ValueError(
                "No target businesses matched (Edmonton Chinese + dim sum/fried rice photos). "
                "Try relaxing conditions or ensure photo captions / Milvus collection are available."
            )

        # 5) Friend reviews on those businesses
        reviews = get_friend_reviews_for_businesses(review_conn, friend_ids, target_biz_ids)
        if not reviews:
            raise ValueError("No reviews by Carl's friends for the selected businesses.")

        # Name mapping
        reviewer_ids = sorted({r["user_id"] for r in reviews})
        names = get_user_names(user_conn, reviewer_ids)

        # Build output rows
        output = []
        for r in reviews:
            bid = r["business_id"]
            b = edm_biz_by_id.get(bid)
            if not b:
                continue
            output.append({
                "friend_name": names.get(r["user_id"], r["user_id"]),
                "friend_user_id": r["user_id"],
                "friend_rating": r["stars"],
                "business_name": b["name"],
                "address": b["address"],
                "city": b["city"],
                "state": b["state"],
                "postal_code": b["postal_code"],
                "business_stars": b["stars"],
                "categories": b["categories"],
                "business_id": bid
            })

        # Sort: by business then rating desc
        output.sort(key=lambda x: (x["business_name"], -(x["friend_rating"] or 0)))

        # Print result
        try:
            import pandas as pd
            df = pd.DataFrame(output)
            cols = [
                "business_name", "address", "city", "state", "postal_code",
                "friend_name", "friend_rating", "business_stars", "categories", "business_id"
            ]
            print(df[cols].to_string(index=False))
        except Exception:
            for row in output:
                print(row)

    finally:
        user_conn.close()
        biz_conn.close()
        photo_conn.close()
        review_conn.close()


if __name__ == "__main__":
    main()
